<main class="festival-gallery-page"><section class="gallery-page-hero"><span class="eyebrow pink">EUPHORIA ARCHIVE / DYNAMIC MEDIA</span><h1>A FESTIVAL<br><em>IN MOTION.</em></h1><p>Photos, video teasers and stage moments published directly by the EUPHORIA team.</p></section><div class="gallery-filter-bar" data-testid="gallery-filters"><button class="active" type="button" data-media-filter="all">All media</button><button type="button" data-media-filter="image">Photos</button><button type="button" data-media-filter="video">Videos</button></div><section class="gallery-masonry" data-testid="gallery-grid"><?php foreach($media as $index=>$item): ?><button class="gallery-media-card gallery-size-<?= $index%5 ?>" type="button" data-media-type="<?= esc($item['media_type']) ?>" data-media-open data-media='<?= esc(json_encode($item),'attr') ?>' data-testid="gallery-item-<?= $item['id'] ?>"><img src="<?= esc($item['preview_url']) ?>" alt="<?= esc($item['caption']?:$item['title']) ?>"><div><span><?= strtoupper(esc($item['media_type'])) ?><?= $item['event_id']?' · EVENT':'' ?></span><h2><?= esc($item['title']) ?></h2><p><?= esc($item['caption']) ?></p></div><?php if($item['media_type']==='video'): ?><b>▶</b><?php endif ?></button><?php endforeach ?></section><?php if(!$media): ?><p class="gallery-empty">No active media has been published yet.</p><?php endif ?><?= view('partials/media_modal') ?></main>